function esc(s){ s=String(s==null?'':s); return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function collagePlan(n, cols, gap, cell){
  n=Math.max(1,(+n)||1);
  cols=Math.max(1,Math.min(n,(+cols)||1));
  var rows=Math.ceil(n/cols);
  var w=cols*cell+(cols-1)*gap, h=rows*cell+(rows-1)*gap;
  var pos=[];
  for(var i=0;i<n;i++){ var r=Math.floor(i/cols), c=i%cols; pos.push({x:c*(cell+gap), y:r*(cell+gap), w:cell, h:cell}); }
  return {w:w, h:h, pos:pos, cols:cols, rows:rows};
}
var EXPORTS={collagePlan:collagePlan, esc:esc};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CollageForgePure = EXPORTS; }
